'use strict';
// V5.2 D concept, integrated with V6.0. Snapshots contain only resolved career results.
const TournamentResultsD={dialog:null,current:null,
 store(){return S.tournamentResultsD??={version:1,notices:[]};},
 eligible(a){const e=S.events.find(e=>e.id===a.event);return e&&a.entrants.includes(S.club)&&!a.withdrawnV12&&!a.spectator13&&!e.background51&&!Qualifiers.isRegional(e);},
 snapshot(a,final=false){const e=S.events.find(e=>e.id===a.event),places=final?e.placements6:a.placements;return a.entrants.map(id=>({id,place:Number.isInteger(places?.[id])?places[id]:null}));},
 capture(a,final=false){
  if(!this.eligible(a))return;const place=(final?S.events.find(e=>e.id===a.event)?.placements6:a.placements)?.[S.club];
  if(!Number.isInteger(place)||(!final&&(place===1||a.schedule.some(n=>n.championship&&n.score))))return;
  const key=a.event+':'+S.club,rows=this.snapshot(a,final),spans={};for(const n of a.schedule)if(n.outPlace)spans[n.outPlace]=(spans[n.outPlace]||0)+1;const old=this.store().notices.find(n=>n.key===key);
  if(old){if(final){old.rows=rows;old.spans=spans;old.final=true;old.place=place;}return;}
  this.store().notices.push({key,event:a.event,club:S.club,day:S.day,kind:place===1?'champions':'eliminated',place,final,rows,spans,shown:false});
 },
 pending(){return (S.tournamentResultsD?.notices||[]).find(n=>!n.shown&&n.club===S.club&&(S.active?S.active.event===n.event:S.events.find(e=>e.id===n.event)?.done));},
 pause(a){const n=this.pending();return !!(n&&!n.final&&S.active===a&&!a.autoCoach13&&!busy13&&typeof document.createElement==='function');},
 range(n,place){if(place==null)return 'В ИГРЕ';const count=Math.max(n.rows.filter(r=>r.place===place).length,n.spans?.[place]||0);return count>1?place+'–'+(place+count-1):String(place);},
 markup(n){
  const e=S.events.find(e=>e.id===n.event),win=n.kind==='champions',rows=[...n.rows].sort((a,b)=>(a.place??Infinity)-(b.place??Infinity)||a.id-b.id),medals=[2,1,3];
  const club=r=>'<div class="rd-logo">'+clubAvatar12(S.teams[r.id],false)+'</div><h2>'+esc(S.teams[r.id].name)+'</h2>';
  return '<section class="rd-card '+(win?'rd-win':'rd-out')+'" aria-labelledby="rd-title"><header><span>ANCIENT MANAGER / TOURNAMENT RECAP</span><button type="button" onclick="TournamentResultsD.close()" aria-label="Пропустить итоги турнира">Пропустить ×</button></header><div class="rd-heading"><small>'+(n.final?'ИТОГОВАЯ ТАБЛИЦА':'ВАШЕ ВЫСТУПЛЕНИЕ ЗАВЕРШЕНО')+'</small><h1 id="rd-title">'+esc(e.name)+'</h1><p>'+(e.season!=null?'ВЫПУСК '+esc(String(e.season))+' · ':'')+(n.final?'ТУРНИР ЗАВЕРШЁН':'ТУРНИР ПРОДОЛЖАЕТСЯ')+'</p></div><div class="rd-podium">'+medals.map(rank=>{const ranked=rows.filter(r=>r.place===rank);return '<article class="rd-medal rd-place-'+rank+'"><small>'+({1:'ЗОЛОТО',2:'СЕРЕБРО',3:'БРОНЗА'})[rank]+'</small><b class="rd-rank">'+rank+'</b>'+(ranked.length?ranked.map(club).join(''):'<div class="rd-unknown">?</div><h2>ЕЩЁ НЕ ОПРЕДЕЛЁН</h2>')+(rank===1?'<div class="rd-trophy">'+Trophy4B.sprite(Trophy4B.select(e).key)+'</div>':'')+'<p>'+(ranked.some(r=>r.id===n.club)?'ВАШ КЛУБ':ranked.length?'МЕСТО ПОДТВЕРЖДЕНО':'Борьба за медали продолжается')+'</p></article>';}).join('')+'</div><div class="rd-table-label"><b>'+(n.final?'ФИНАЛЬНОЕ РАСПРЕДЕЛЕНИЕ МЕСТ':'ТЕКУЩИЕ РЕЗУЛЬТАТЫ')+'</b><small>'+n.rows.length+' УЧАСТНИКОВ</small></div><div class="rd-table">'+rows.filter(r=>r.place==null||r.place>3).map((r,i)=>'<article class="rd-row '+(r.id===n.club?'rd-own':'')+'" style="--delay:'+Math.min(i*.04,.5)+'s"><b>'+this.range(n,r.place)+'</b>'+clubAvatar12(S.teams[r.id],true)+'<strong>'+esc(S.teams[r.id].name)+'</strong><small>'+(r.id===n.club?'ВАШ КЛУБ':r.place==null?'В ИГРЕ':'')+'</small></article>').join('')+'</div><footer><div><small>'+esc(S.teams[n.club].name)+' / ВАШ РЕЗУЛЬТАТ</small><h2>'+(win?'ВЫ — ЧЕМПИОНЫ':'ВЫСТУПЛЕНИЕ ЗАВЕРШЕНО')+'</h2><p>'+(n.final?'Результаты этого турнира сохранены в карьере.':'Неопределённые места обновятся после финала.')+'</p></div><strong class="rd-result">'+this.range(n,n.place)+'</strong><b class="rd-status">'+(win?'CHAMPIONS':'ELIMINATED')+'</b><button type="button" onclick="TournamentResultsD.close()">Продолжить →</button></footer></section>';
 },
 show(n){if(this.dialog||typeof document.createElement!=='function')return;const d=document.createElement('dialog');d.id='tournamentResultsD';d.className='rd-dialog';d.setAttribute('aria-label','Итоги турнира');d.innerHTML=this.markup(n);this.dialog=d;this.current=n;document.body.appendChild(d);d.addEventListener('cancel',ev=>{ev.preventDefault();this.close();});d.addEventListener('close',()=>{if(this.dialog===d)this.close();else d.remove();});d.showModal();d.querySelector('header button').focus();d.scrollTop=0;},
 present(){if(this.dialog||busy13||S.practice13||S.active?.autoCoach13||Background51.finishing||typeof document.querySelector!=='function'||document.querySelector('dialog[open]'))return;const n=this.pending();if(n)this.show(n);},
 dispose(){const d=this.dialog;this.dialog=null;this.current=null;if(d?.open)d.close();d?.remove();},
 close(){const n=this.current;if(!n){this.dispose();return;}n.shown=true;const resume=S.active?.event===n.event&&!n.final;this.dispose();save();if(resume)seekMatch6();else render();}
};
const recordBeforeResultsD=recordNode6;recordNode6=function(a,...args){const r=recordBeforeResultsD(a,...args);if(S.active===a)TournamentResultsD.capture(a);return r;};
const phaseBeforeResultsD=phaseNext6;phaseNext6=function(a,...args){const r=phaseBeforeResultsD(a,...args);if(S.active===a)TournamentResultsD.capture(a);return r;};
const seekBeforeResultsD=seekMatch6;seekMatch6=function(...args){if(S.active&&TournamentResultsD.pause(S.active)){go('bracket');return;}return seekBeforeResultsD(...args);};
const finishBeforeResultsD=finishEvent6;finishEvent6=function(a,...args){const r=finishBeforeResultsD(a,...args);if(S.events.find(e=>e.id===a.event)?.done){TournamentResultsD.capture(a,true);save();render();}return r;};
const renderBeforeResultsD=render;render=function(...args){const r=renderBeforeResultsD(...args);if(S)TournamentResultsD.present();return r;};
const playBeforeResultsD=playMap,advanceBeforeResultsD=advanceMap;
playMap=function(...args){if(S.active&&TournamentResultsD.pause(S.active)){TournamentResultsD.present();return;}return playBeforeResultsD(...args);};
advanceMap=function(...args){if(S.active&&TournamentResultsD.pause(S.active)){TournamentResultsD.present();return;}return advanceBeforeResultsD(...args);};
const freshBeforeResultsD=fresh,migrateBeforeResultsD=migrate;
fresh=function(...args){TournamentResultsD.dispose();return freshBeforeResultsD(...args);};
migrate=function(...args){TournamentResultsD.dispose();const r=migrateBeforeResultsD(...args);if(S.tournamentResultsD)S.tournamentResultsD.notices=S.tournamentResultsD.notices.filter(n=>n.day<=S.day&&S.events.some(e=>e.id===n.event));return r;};
const validBeforeResultsD=validSave;validSave=function(x){if(!validBeforeResultsD(x))return false;const v=x.tournamentResultsD;if(!v)return true;if(v.version!==1||!Array.isArray(v.notices))return false;const keys=new Set();return v.notices.every(n=>{if(typeof n.key!=='string'||keys.has(n.key)||!x.events.some(e=>e.id===n.event)||!x.teams[n.club]||!Number.isInteger(n.day)||n.day>x.day||!['champions','eliminated'].includes(n.kind)||!Number.isInteger(n.place)||n.place<1||typeof n.final!=='boolean'||typeof n.shown!=='boolean'||!Array.isArray(n.rows)||!n.rows.length||new Set(n.rows.map(r=>r.id)).size!==n.rows.length||n.rows.some(r=>!Number.isInteger(r.id)||!x.teams[r.id]||(r.place!==null&&(!Number.isInteger(r.place)||r.place<1||r.place>n.rows.length))))return false;if(n.key!==n.event+':'+n.club||!n.rows.some(r=>r.id===n.club&&r.place===n.place)||(n.kind==='champions')!==(n.place===1))return false;if(n.spans&&(typeof n.spans!=='object'||Array.isArray(n.spans)||Object.entries(n.spans).some(([p,c])=>!Number.isInteger(Number(p))||Number(p)<1||!Number.isInteger(c)||c<1||Number(p)+c-1>n.rows.length)))return false;keys.add(n.key);return true;});};
const bracketBeforeResultsD=bracketView;bracketView=function(...args){const html=bracketBeforeResultsD(...args),event=selectedBracket??S.active?.event,n=(S.tournamentResultsD?.notices||[]).find(n=>n.event===event&&n.club===S.club);return html+(n?'<section class="panel"><h2>Итоги выступления</h2>'+btn('Показать итоги турнира','showTournamentResultsD('+n.event+')')+'</section>':'');};
function showTournamentResultsD(event){const n=S.tournamentResultsD?.notices.find(n=>n.event===event&&n.club===S.club);if(n)TournamentResultsD.show(n);}
